    /* ---------- \u624B\u5199\u6807\u6CE8\u5C42 ---------- */
    ".hvv-ink{position:absolute;left:0;top:0;width:100%;height:100%;z-index:5;pointer-events:none;touch-action:none;}",
    ".hvv-root.is-ink .hvv-ink{pointer-events:auto;}",
